<?php /** @var array $ev, $rows */ $max = max(1, ...array_map(fn($r) => (int)$r['n'], $rows ?: [['n' => 1]])); ?>
<div class="page-head"><div><p class="muted" style="margin-top:0">Qui a scanné quoi, où et à quel rythme : pour équilibrer les équipes aux entrées et repérer un appareil qui travaille hors ligne.</p></div><a class="btn btn-light" href="?format=csv">Export CSV</a></div>
<div class="card table-card"><?php if (!$rows): ?><p class="muted" style="padding:20px">Aucun scan pour l'instant.</p><?php else: ?>
<table class="table"><thead><tr><th>Opérateur ou appareil</th><th>Volume</th><th class="num">Entrées</th><th class="num">Sorties</th><th class="num">Refus</th><th class="num">Hors ligne</th><th>Points d'accès</th><th>Rythme</th><th>Activité</th></tr></thead><tbody>
<?php foreach ($rows as $r): $span = max(1, strtotime((string)$r['last_at']) - strtotime((string)$r['first_at'])); $rate = $span > 300 ? round((int)$r['n'] / ($span / 60), 1) : null; ?><tr>
  <td><b><?= e($r['who']) ?></b></td><td style="min-width:120px"><div class="bar-track"><i style="width:<?= round((int)$r['n'] / $max * 100) ?>%"></i></div><small><?= (int)$r['n'] ?> scans</small></td>
  <td class="num"><?= (int)$r['ok'] ?></td><td class="num"><?= (int)$r['exits'] ?></td><td class="num"><?= (int)$r['refused'] ?><?= (int)$r['n'] ? ' <small class="muted">(' . round((int)$r['refused'] / (int)$r['n'] * 100) . ' %)</small>' : '' ?></td>
  <td class="num"><?= (int)$r['offline'] ?></td><td><small><?= e((string)$r['point_names'] ?: '—') ?></small></td><td><?= $rate !== null ? e(str_replace('.', ',', (string)$rate)) . ' / min' : '—' ?></td>
  <td><small><?= e(date('d/m H:i', strtotime((string)$r['first_at']))) ?> → <?= e(date('H:i', strtotime((string)$r['last_at']))) ?></small></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
